import machine
wdt = machine.WDT(timeout=10000)
# Add-a-word demo: camera, v2 top-3; a word typed on the PC joins the word list (runs until stopped)
# Generated by release/live/make_live.py (overnight 2, Part 5). The known-good demo files are not touched.
# OpenMV N6, firmware 5.0.1. Model mci0_256_w3u_splitdw4 (ROMFS 0x70f2b1c0). WDT 10 s first; fed in every loop and
# around every predict. The board only READS /flash/liveword.bin; nothing is written to the board's drive.
import time, gc, uctypes, binascii, struct, math, image, csi, ml

# ---------------------------------------------------------------- configuration
MODEL_NAME = "mci0_256_w3u_splitdw4"
EXPECT = {"mci0_256_w3u_splitdw4": (0x70f2b1c0, 12723288)}  # (addr, size)
TEXT_SOURCE = "embedded"         # 43-word list (W5's 41 + painting, mirror), night/demo_run/pc/vocab43
FRAMESIZE = csi.QVGA
LOGIT_SCALE = 67.2256            # exp(logit_scale) of checkpoints/mobileclip_s0.pt, only for the % display
PRINT_EVERY = 1                  # print one result line every N frames
IO = [0.0, 0, 0.0, 0]            # in_scale, in_zp, out_scale, out_zp (read from ml.Model)
LUT = [None]; LUT_XOR = [True]; ROI = [None]; SRC = [None]; OUT = [None]; CAPTURE = [None]
T_FILL = [0]; T_PRED = [0]

# ---------------------------------------------------------------- core (shared by demo.py and validate_input.py)
# APIs used and where they were checked (OpenMV firmware 5.0.1 source, ext/openmv-5.0.1):
#   csi.CSI().reset/pixformat/framesize/snapshot(time=)  modules/py_csi_ng.c; same calls as board/check_yolo_cut.py
#   image.Image(w, h, image.GRAYSCALE, buffer=...)        modules/py_image.c py_image_make_new (buffer kw)
#   img.draw_image(src, 0, 0, roi=, rgb_channel=, hint=)  modules/py_image.c py_image_line_op, lib/imlib/draw.c
#   img.to_ndarray("b", buffer=...)                       modules/py_image.c py_image_to_ndarray (GRAYSCALE: u8 ^ 0x80)
#   img.draw_string((x, y), s, color=, scale=)            modules/py_image.c py_image_draw_string (xy is ONE tuple)
#   img.draw_rectangle((x, y, w, h), color=, fill=)       modules/py_image.c py_image_draw_rectangle
#   img.get_pixel((x, y), rgbtuple=)                      modules/py_image.c py_image_get_pixel
#   ml.Model(path); m.predict([fill], callback=cb)        modules/py_ml.c (fill(buf, shape, dtype) gets the input
#     tensor as a bytearray BY REFERENCE; cb(model, inputs, outputs) gets outputs[0] = ulab ndarray VIEW of the output
#     tensor; input_scale / input_zero_point / ... are tuples, one item per tensor)
#   ml/model.py wrapper (scripts/libraries/ml/ml-core): ml.Model -> uml.Model, labels from <path>.txt if present
#   math.exp: used by scripts/libraries/ml/ml-core/ml/utils.py
#   uctypes.addressof(open(rom file)), binascii.crc32 / a2b_base64 / b2a_base64, struct.unpack("<512f"),
#   bytes(outputs[0].tobytes()) inside the callback: all used by board scripts that ran on this board (board/i16_*.py,
#   board/stem4_*.py).
# The input tensor and the output tensor share ONE buffer (REPORT "Board vs ORT - fact collection" 0d/1c), so the
# input is rewritten by fill() before EVERY predict and the output is copied inside the callback.

def step(s):
    print(s)
    time.sleep_ms(30)                # the IDE terminal drops unpaced lines (REPORT "Stem: where does the board round?")


def start_wait():
    for _ in range(6):               # 3 s: the IDE terminal drops the first ~0.5 s of output
        time.sleep_ms(500)
        wdt.feed()


# ---- text embeddings (format MCTX v1, see night/W5_demo/README.md) ----
def parse_text(b, names):
    if bytes(b[0:4]) != b"MCTX":
        raise ValueError("demo_text: bad magic")
    ver, n, d, mode, crc = struct.unpack("<HHHHI", b[4:16])
    body = b[16:]
    if ver != 1 or len(body) != 4 * n + n * d:
        raise ValueError("demo_text: bad version/size")
    if (binascii.crc32(body) & 0xFFFFFFFF) != crc:
        raise ValueError("demo_text: CRC32 mismatch")
    if len(names) != n:
        raise ValueError("demo_text: %d names for %d rows" % (len(names), n))
    rows = []
    norms = []
    o = 16 + 4 * n
    for i in range(n):
        r = struct.unpack("<%db" % d, b[o + i * d:o + (i + 1) * d])
        rows.append(r)
        norms.append(sum([x * x for x in r]) ** 0.5)
        if i % 8 == 7:
            wdt.feed()
    return rows, norms, mode, crc, d


def load_text():
    if TEXT_SOURCE == "embedded":
        b = binascii.a2b_base64(TEXT_B64)
        names = TEXT_NAMES.split("\n")
    elif TEXT_SOURCE == "rom":
        f = open("/rom/demo_text.bin", "rb"); b = f.read(); f.close()
        f = open("/rom/demo_text.txt", "r"); names = [l.strip() for l in f.read().split("\n") if l.strip()]; f.close()
    elif TEXT_SOURCE == "module":
        import demo_text
        b = binascii.a2b_base64(demo_text.BIN_B64)
        names = list(demo_text.NAMES)
    else:
        raise ValueError("TEXT_SOURCE must be embedded | rom | module")
    wdt.feed()
    rows, norms, mode, crc, d = parse_text(b, names)
    step("T text source=%s entries=%d dim=%d prompt_mode=%s crc32=0x%08x" % (
        TEXT_SOURCE, len(names), d, ("templates80", "simple")[mode] if mode < 2 else str(mode), crc))
    return names, rows, norms


# ---- model ----
def open_model():
    path = "/rom/" + MODEL_NAME
    f = open(path, "rb"); a = uctypes.addressof(f) & 0xFFFFFFFF; f.close()
    e = EXPECT.get(MODEL_NAME)
    step("A0 %s at 0x%08x mod8=%d%s" % (MODEL_NAME, a, a % 8, "" if e is None else (
        " expected 0x%08x %s" % (e[0], "MATCH" if a == e[0] else "MISMATCH (info only)"))))
    if a % 8:
        step("STOP: model address is not 8-byte aligned, no predict")
        raise SystemExit
    wdt.feed(); gc.collect()
    m = ml.Model(path)
    wdt.feed()
    step("A1 %s" % (m,))
    ok = (len(m.input_shape) == 1 and tuple(m.input_shape[0]) == (1, 3, 256, 256) and m.input_dtype[0] == "b"
          and len(m.output_shape) == 1 and tuple(m.output_shape[0]) == (1, 512) and m.output_dtype[0] == "b"
          and m.output_scale[0] > 0)
    if not ok:
        step("STOP: unexpected model I/O (need int8 input (1,3,256,256) NCHW and int8 output (1,512))")
        raise SystemExit
    if e is not None and m.len != e[1]:
        step("WARN model_size %d, expected %d" % (m.len, e[1]))
    IO[0] = m.input_scale[0]; IO[1] = m.input_zero_point[0]; IO[2] = m.output_scale[0]; IO[3] = m.output_zero_point[0]
    make_lut(IO[0], IO[1])
    step("A2 in_scale=%r in_zp=%d out_scale=%r out_zp=%d lut=%s" % (IO[0], IO[1], IO[2], IO[3],
                                                                     "xor80" if LUT_XOR[0] else "table"))
    return m


def make_lut(s, z):
    """q = clamp(round_half_even(p / 255 / s) + z, -128, 127) for every pixel value p, s/z READ from ml.Model."""
    lut = bytearray(256)
    xor = True
    for p in range(256):
        v = (p / 255) / s
        fl = int(v // 1)
        d = v - fl
        q = fl + (1 if (d > 0.5 or (d == 0.5 and fl % 2 == 1)) else 0) + z
        q = -128 if q < -128 else (127 if q > 127 else q)
        lut[p] = q & 0xFF
        if lut[p] != ((p - 128) & 0xFF):
            xor = False
    LUT[0] = bytes(lut)
    LUT_XOR[0] = xor


# ---- preprocessing: centre square crop -> 256x256 bilinear -> R, G, B planes (NCHW) -> int8 ----
def set_source(img):
    w = img.width(); h = img.height(); s = w if w < h else h
    ROI[0] = ((w - s) // 2, (h - s) // 2, s, s)
    SRC[0] = img


def draw_planes(mv):
    """Camera source: centre square (ROI[0]) of SRC[0] -> 256x256 bilinear -> R, G, B uint8 planes (NCHW order)."""
    src = SRC[0]; roi = ROI[0]
    for c in range(3):                               # plane c = channel c of NCHW: 0 = R, 1 = G, 2 = B
        image.Image(256, 256, image.GRAYSCALE, buffer=mv[c * 65536:(c + 1) * 65536]).draw_image(
            src, 0, 0, roi=roi, rgb_channel=c, hint=image.BILINEAR | image.SCALE_ASPECT_IGNORE)


SOURCE = [draw_planes]                               # demo_run 9.11: the known-answer test swaps in a file source


def fill(buf, shape, dtype):
    """predict() input callback: writes the WHOLE int8 input tensor (196,608 bytes) from SRC[0] / ROI[0]."""
    t0 = time.ticks_us()
    if dtype != 98 or len(buf) != 196608:            # 98 = ord("b")
        raise ValueError("unexpected input tensor %r %r %r" % (len(buf), shape, dtype))
    SOURCE[0](memoryview(buf))                       # writes the three uint8 planes (camera: draw_planes)
    if LUT_XOR[0]:                                   # LUT[p] == p - 128: in place u8 -> u8 ^ 0x80 (C, vectorized)
        image.Image(256, 768, image.GRAYSCALE, buffer=buf).to_ndarray("b", buffer=buf)
    else:                                            # other input scale/zp: generic table (slow, Python)
        lut = LUT[0]
        for i in range(196608):
            buf[i] = lut[buf[i]]
            if (i & 16383) == 0:
                wdt.feed()
    if CAPTURE[0] is not None:
        CAPTURE[0].append(bytes(buf))                # exact input bytes (validation only), before the NPU runs
    T_FILL[0] = time.ticks_diff(time.ticks_us(), t0)


def grab(model, inputs, outputs):
    """predict() output callback: copy the int8 output NOW (the buffer is shared with the next input)."""
    OUT[0] = bytes(outputs[0].tobytes())
    return None


def predict(m):
    wdt.feed()
    t0 = time.ticks_us()
    m.predict([fill], callback=grab)
    T_PRED[0] = time.ticks_diff(time.ticks_us(), t0)
    wdt.feed()
    return OUT[0]


# ---- scoring ----
def score(ob, rows, norms):
    """dequantize (q - zp) * out_scale -> L2-normalize -> cosine with every text row.
    The positive factor out_scale and the int8 row scales cancel in the cosine, so it is computed exactly in integers:
    cos_i = (q_i . v) / (|q_i| |v|) with v = q_out - zp_out."""
    zp = IO[3]
    v = [(x - 256 if x > 127 else x) - zp for x in ob]
    nv = sum([x * x for x in v]) ** 0.5
    sc = []
    for i in range(len(rows)):
        t = rows[i]
        s = 0
        for k in range(512):
            s += t[k] * v[k]
        sc.append(s / (norms[i] * nv) if nv > 0 else 0.0)
    return sc


def top3(sc):
    idx = sorted(range(len(sc)), key=lambda i: -sc[i])[:3]
    mx = sc[idx[0]]
    z = sum([math.exp(LOGIT_SCALE * (x - mx)) for x in sc])
    return [(i, sc[i], math.exp(LOGIT_SCALE * (sc[i] - mx)) / z) for i in idx]


def check_frame(img):
    if img.format() != image.RGB565:
        step("STOP: camera frame is not RGB565 (format %r)" % (img.format(),))
        raise SystemExit


def open_camera():
    cam = csi.CSI()
    wdt.feed()
    cam.reset()
    wdt.feed()
    cam.pixformat(csi.RGB565)
    cam.framesize(FRAMESIZE)
    wdt.feed()
    cam.snapshot(time=2000)                          # let exposure / white balance settle (2 s < WDT 10 s)
    wdt.feed()
    return cam


# ---------------------------------------------------------------- v2 library (overnight 2, 10.11)
# What is new compared with the known-good demo (the model, the camera path and the input bytes are NOT changed:
# set_source / draw_planes / fill / predict / grab above are the known-good core, byte for byte):
#   1. scoring with ulab (C, vectorised) instead of the pure-Python loop: same cosine, ~1 ms instead of ~22 ms
#   2. smoothing: exponential moving average (EMA) of the unit image embedding, m = (1 - ALPHA) * m + ALPHA * e
#   3. "?" when unsure: the #1 word is shown only if (cos #1 - cos #2) >= THR_ON; once shown it stays while it is
#      still #1 and its margin is >= THR_OFF (hysteresis, so the label does not flicker at the threshold)
#   4. the per-frame line is printed without the 30 ms pause (one line per ~180 ms frame is already paced)
# ulab calls used here were all proven on this board in run A (release/logs/p2_cap_emb_dark.txt, U lines).
from ulab import numpy as np

ALPHA = 0.2                      # EMA weight of the newest frame (1.0 = no smoothing)
THR_ON = 0.012                   # show a word when its cosine margin over #2 is at least this
THR_OFF = 0.006                  # keep the shown word while it is #1 and its margin is at least this
MAX_FRAMES = 0                   # 0 = run until stopped
PROFILE = 0                      # 1 = also time the resize inside fill() (adds a wrapper call)
V2 = {"Tf": None, "ema": None, "label": -1}
CNT = [0, 0, 0, 0, 0]            # frames, raw #1 changes, smoothed #1 changes, shown-label changes, unsure frames
PREV = [None, None, None]        # previous raw #1, smoothed #1, shown label
T_SC = [0, 0]                    # us: raw scoring (unit + cosine + top-2), smoothing + top3 + decision
T_RS = [0]                       # us: resize part of fill() (only with PROFILE)


def crc(b):
    return binascii.crc32(b) & 0xFFFFFFFF


def nm(names, i):
    return "?" if i < 0 else names[i].replace(" ", "_")


def setup_text_ulab(norms):
    """Unit-length float rows of the words, from the same embedded bytes that load_text() parsed."""
    if TEXT_SOURCE != "embedded":
        raise ValueError("v2 needs TEXT_SOURCE = embedded")
    b = binascii.a2b_base64(TEXT_B64)
    n = len(norms)
    Ti = np.frombuffer(b[16 + 4 * n:], dtype=np.int8).reshape((n, 512))
    Tf = np.array(Ti, dtype=np.float)
    for i in range(n):
        Tf[i] = Tf[i] / norms[i]
    wdt.feed()
    V2["Tf"] = Tf
    reset_state()


def reset_state():
    V2["ema"] = None; V2["label"] = -1
    PREV[0] = None; PREV[1] = None; PREV[2] = None
    for i in range(len(CNT)):
        CNT[i] = 0


def unit(ob):
    """int8 output bytes -> unit-length float vector (the output scale cancels; zero point is 0 for this model)."""
    v = np.array(np.frombuffer(ob, dtype=np.int8), dtype=np.float)
    if IO[3]:
        v = v - IO[3]
    nv = np.linalg.norm(v)
    return v / nv if nv > 0 else v


def top2(l):
    a = 0 if l[0] >= l[1] else 1
    b = 1 - a
    for i in range(2, len(l)):
        x = l[i]
        if x > l[a]:
            b = a; a = i
        elif x > l[b]:
            b = i
    return a, b


def smooth(e):
    """EMA of the unit embedding; returns the cosine of the smoothed vector with every word (ulab array)."""
    m = V2["ema"]
    m = e if m is None else m * (1.0 - ALPHA) + e * ALPHA
    V2["ema"] = m
    return np.dot(V2["Tf"], m) / np.linalg.norm(m)


def decide(top):
    """top = top3() of the smoothed scores. Returns (shown word index or -1 for '?', margin #1 - #2)."""
    i0 = top[0][0]
    margin = top[0][1] - top[1][1]
    cur = V2["label"]
    if not (cur == i0 and margin >= THR_OFF):
        cur = i0 if margin >= THR_ON else -1
    V2["label"] = cur
    return cur, margin


def process(m):
    """One frame, after SRC[0] / ROI[0] are set. Returns (output bytes, raw #1, raw cos #1, raw margin,
    smoothed top-3 [(i, cos, p)], shown label, smoothed margin)."""
    ob = predict(m)                                  # known-good core: fill() -> NPU -> copy of the 512 int8
    t0 = time.ticks_us()
    e = unit(ob)
    lr = np.dot(V2["Tf"], e).tolist()                # raw cosines = what the known-good demo scores
    r1, r2 = top2(lr)
    t1 = time.ticks_us()
    top = top3(smooth(e).tolist())
    label, margin = decide(top)
    t2 = time.ticks_us()
    T_SC[0] = time.ticks_diff(t1, t0); T_SC[1] = time.ticks_diff(t2, t1)
    CNT[0] += 1
    if PREV[0] is not None:
        CNT[1] += 1 if r1 != PREV[0] else 0
        CNT[2] += 1 if top[0][0] != PREV[1] else 0
        CNT[3] += 1 if label != PREV[2] else 0
    CNT[4] += 1 if label < 0 else 0
    PREV[0] = r1; PREV[1] = top[0][0]; PREV[2] = label
    return ob, r1, lr[r1], lr[r1] - lr[r2], top, label, margin


def timed_src(mv):
    t0 = time.ticks_us()
    draw_planes(mv)
    T_RS[0] = time.ticks_diff(time.ticks_us(), t0)


def overlay_v2(img, names, top, label, fps):
    """Same layout as the known-good overlay. New: the first line is yellow with a leading '?' when unsure."""
    x0, y0, w, h = ROI[0]
    img.draw_rectangle((x0, y0, w, h), color=(255, 255, 0))          # the area that the model sees
    img.draw_rectangle((x0, y0, w, 62), color=(0, 0, 0), fill=True)
    for r in range(len(top)):
        i, c, p = top[r]
        t = "%s %d%%" % (names[i], int(p * 100 + 0.5))
        col = (255, 255, 255)
        if r == 0:
            if label < 0:
                t = "? " + t; col = (255, 255, 0)
            else:
                col = (0, 255, 0)
        img.draw_string((x0 + 4, y0 + 2 + 20 * r), t, color=col, scale=2)
    img.draw_string((x0 + 4, y0 + h - 12), "cos %.2f %.2f %.2f  %.2f fps" % (top[0][1], top[1][1], top[2][1], fps),
                    color=(255, 255, 0), scale=1)


# ---------------------------------------------------------------- live word library (overnight 2, Part 5)
# The typed word arrives in ONE fixed-size file on the board's own drive: /flash/liveword.bin (the PC sees the same
# file as E:\liveword.bin and overwrites it in place). The board re-opens and reads the file once per frame and
# NEVER writes to the drive.
# Layout (1024 bytes, little endian): 0 "MCLW" | 4 u16 version = 1 | 6 u16 seq | 8 u32 crc32 of bytes 12..1023 |
#   12 f32 row scale | 16 u32 PC ms | 20 u8 word length | 21 word, utf-8, 64 bytes | 512 the 512 int8 values.
# A word is taken only when seq is new AND the CRC is right. Otherwise the previous word stays, and a half-written
# file is simply read again on the next frame.
LW_PATH = "/flash/liveword.bin"
LW = {"seq": -1, "word": "", "M": None, "have": 0, "taken": 0, "bad": 0, "err": 0, "pc_ms": 0, "last_err": ""}
LW_BUF = bytearray(1024)
T_LW = [0, 0]                    # us: last poll (open + read + close + header check), last take (crc + parse)
LW_PAL = [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0), (255, 0, 255), (0, 255, 255)]   # marker = seq % 6


def lw_setup():
    LW["M"] = np.array(np.frombuffer(bytes(512), dtype=np.int8).reshape((1, 512)), dtype=np.float)


def lw_poll():
    """Read the file. Returns True when a new word was taken on this call."""
    t0 = time.ticks_us()
    n = -1
    try:
        f = open(LW_PATH, "rb")
        try:
            n = f.readinto(LW_BUF)
        finally:
            f.close()
    except OSError as e:
        LW["err"] += 1; LW["last_err"] = repr(e)
        T_LW[0] = time.ticks_diff(time.ticks_us(), t0)
        return False
    b = LW_BUF
    took = False
    if n == 1024 and b[0] == 77 and b[1] == 67 and b[2] == 76 and b[3] == 87 and b[4] == 1 and b[5] == 0:   # "MCLW", 1
        seq = b[6] | (b[7] << 8)
        T_LW[0] = time.ticks_diff(time.ticks_us(), t0)
        if seq != LW["seq"]:
            t1 = time.ticks_us()
            wl = b[20]
            if crc(memoryview(b)[12:]) == struct.unpack_from("<I", b, 8)[0] and 0 < wl <= 64:
                v = np.array(np.frombuffer(b[512:1024], dtype=np.int8), dtype=np.float)
                nv = np.linalg.norm(v)
                if nv > 0:
                    try:
                        w = bytes(b[21:21 + wl]).decode()
                    except Exception:
                        w = "?"
                    LW["M"][0] = v / nv
                    LW["seq"] = seq; LW["word"] = w; LW["pc_ms"] = struct.unpack_from("<I", b, 16)[0]
                    LW["have"] = 1; LW["taken"] += 1
                    took = True
            if not took:
                LW["bad"] += 1
            T_LW[1] = time.ticks_diff(time.ticks_us(), t1)
    else:
        LW["bad"] += 1
        T_LW[0] = time.ticks_diff(time.ticks_us(), t0)
    return took


def lw_cos(e, en):
    """Cosine of the typed word with the embedding e (ulab vector of 512 with length en)."""
    return np.dot(LW["M"], e).tolist()[0] / en


def lw_rank(cw, cosines):
    """1 = the typed word scores higher than every one of the built-in words."""
    r = 1
    for x in cosines:
        if x > cw:
            r += 1
    return r


def overlay_live(img, cw, rank, nwords):
    """Adds the typed word (bottom of the model's area) and the seq colour marker (left margin) to the v2 overlay."""
    x0, y0, w, h = ROI[0]
    img.draw_rectangle((x0, y0 + h - 48, w, 34), color=(0, 0, 0), fill=True)
    if LW["have"]:
        col = (0, 255, 0) if rank == 1 else ((255, 255, 0) if rank <= 3 else (255, 255, 255))
        img.draw_string((x0 + 4, y0 + h - 46), "> " + LW["word"], color=col, scale=2)
        img.draw_string((x0 + 4, y0 + h - 24), "cos %.3f rank %d/%d" % (cw, rank, nwords + 1),
                        color=col, scale=1)
        if x0 >= 58:
            img.draw_rectangle((4, 4, 50, 50), color=LW_PAL[LW["seq"] % 6], fill=True)
    else:
        img.draw_string((x0 + 4, y0 + h - 46), "> (no word)", color=(255, 255, 255), scale=2)


# ---------------------------------------------------------------- "add a word" demo, camera loop (11.11)
# = the demo v2 loop (smoothing, "?" when unsure, top-3), but a word typed on the PC is ADDED to the word list:
# from the next frame on it is scored, ranked, smoothed and shown exactly like the 43 built-in words (top-3 lines,
# percentages, "?" rule). Nothing is drawn at the bottom except a small word counter ("43 words" -> "44 words").
# The word that is in /flash/liveword.bin when the script starts is NOT added (the demo starts with the 43 words);
# only words the PC writes after the start are added. The same word again (e.g. the exact vector after the quick
# "word ..." one) replaces its own row. The board only READS the file.
# Output lines:
#   VA ADD <word> row <i> words <n> seq <s> t <ms> k <frame>     a word was added / replaced
#   V <frame> words <n> | show <label> | top3 <w> <cos> <w> <cos> <w> <cos> | <fps> fps t <ms>
VA_FRAMES = 0                    # 0 = until stopped


def va_add(names, n0):
    """Adds the word just taken by lw_poll() as a row of V2["Tf"] (or replaces its row). Returns its row index."""
    w = LW["word"]
    if w.endswith(" ..."):
        w = w[:-4]
    w = w.strip()
    Tf = V2["Tf"]
    n = len(names)
    for i in range(n0, n):
        if names[i] == w:
            Tf[i] = LW["M"][0]
            return i
    T2 = np.array(np.frombuffer(bytes(512 * (n + 1)), dtype=np.int8).reshape((n + 1, 512)), dtype=np.float)
    for i in range(n):
        T2[i] = Tf[i]
    T2[n] = LW["M"][0]
    V2["Tf"] = T2
    names.append(w)
    gc.collect()
    return n


def overlay_count(img, nwords, n0):
    x0, y0, w, h = ROI[0]
    t = "%d words" % nwords
    if nwords > n0:
        t += " (+%d)" % (nwords - n0)
    img.draw_string((x0 + w - 8 * len(t) - 4, y0 + h - 24), t, color=(255, 255, 0), scale=1)


def main():
    start_wait()
    step("VA demo: model=%s text=%s file=%s ALPHA=%.2f THR_ON=%.4f THR_OFF=%.4f VA_FRAMES=%d (typed words join the word list; the board only reads the file; Stop or the end: the WDT resets the board ~10 s later, expected)" % (
        MODEL_NAME, TEXT_SOURCE, LW_PATH, ALPHA, THR_ON, THR_OFF, VA_FRAMES))
    names, rows, norms = load_text()
    setup_text_ulab(norms)
    del rows
    gc.collect()
    lw_setup()
    lw_poll()                                        # baseline: the word already in the file is NOT added
    step("VA baseline seq=%d word=%s (not added)" % (LW["seq"], LW["word"]))
    LW["have"] = 0
    n0 = len(names)
    cam = open_camera()
    m = open_model()                                 # alignment check BEFORE the first predict
    k = 0
    t_prev = None
    fps = 0.0
    while VA_FRAMES == 0 or k < VA_FRAMES:
        wdt.feed()
        t_now = time.ticks_us()
        if t_prev is not None:
            fps = 1000000.0 / max(1, time.ticks_diff(t_now, t_prev))
        t_prev = t_now
        img = cam.snapshot()
        set_source(img)
        if k == 0:
            check_frame(img)
            step("C frame %dx%d roi=%r" % (img.width(), img.height(), ROI[0]))
        if lw_poll():
            r = va_add(names, n0)
            print("VA ADD %s row %d words %d seq %d t %d k %d" % (names[r], r, len(names), LW["seq"],
                                                                   time.ticks_ms(), k))
        ob, r1, rc, rm, top, label, margin = process(m)   # wdt.feed() before and after the predict inside
        overlay_v2(img, names, top, label, fps)
        overlay_count(img, len(names), n0)
        print("V %d words %d | show %s | top3 %s %.4f %s %.4f %s %.4f | %.2f fps t %d" % (
            k, len(names), nm(names, label), nm(names, top[0][0]), top[0][1], nm(names, top[1][0]), top[1][1],
            nm(names, top[2][0]), top[2][1], fps, time.ticks_ms()))
        k += 1
        wdt.feed()
    step("VA DONE frames=%d words=%d taken=%d bad=%d err=%d" % (k, len(names), LW["taken"], LW["bad"], LW["err"]))



